insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 1, 'Why do well logs measure physical responses such as radioactivity and resistivity instead of reservoir properties directly?', '["No tool can measure rock and fluid properties directly downhole, so physics proxies are converted into them","Direct measurements are possible but regulators require indirect ones","Physical responses are only recorded for quality control of the drilling mud","Logging tools are calibrated in API units which prevents direct measurement"]'::jsonb, 0, 'Tools sense physical responses of the formation; petrophysics is the discipline of converting those proxies into shale volume, porosity and saturation.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 2, 'Which three measurements make up the classic triple combo?', '["Caliper, sonic and neutron","Gamma ray, density and resistivity","Gamma ray, sonic and caliper","Neutron, density and sonic"]'::jsonb, 1, 'GR, bulk density and resistivity form the minimum suite for a standard evaluation; neutron and sonic usually ride along.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 3, 'Shales read high on the gamma ray log because', '["they are denser than sands","their bound water conducts electricity","clay minerals concentrate potassium, thorium and uranium","they are usually washed out"]'::jsonb, 2, 'Natural gamma radioactivity comes from K, Th and U, which clay minerals concentrate.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 4, 'At 2020 m the typewell reads GR 20 API, RHOB 2.3035 g/cc and RT 9.2554 ohm.m. Compared with the shale at 2000 m, this signature is', '["more radioactive, denser and more conductive","quieter on GR, lighter on density and more resistive","identical within tool accuracy","quieter on GR but denser and more conductive"]'::jsonb, 1, 'The shale reads about 120 API, 2.55 g/cc and 2 ohm.m, so the sand is cleaner, lighter and several times more resistive.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 5, 'What is mud filtrate invasion?', '["Formation water flowing into the borehole during drilling","Mud solids dissolving into formation water","Cuttings falling back into the hole and contaminating the mud","The liquid part of the mud being pushed into permeable formations by overbalance pressure"]'::jsonb, 3, 'Borehole pressure exceeds formation pressure, so mud filtrate enters permeable beds while the solids plaster the wall as mudcake.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 6, 'Water saturation work needs the resistivity of which zone around the borehole?', '["The uninvaded zone, written Rt","The flushed zone, written Rxo","The mudcake","The transition zone"]'::jsonb, 0, 'Only the uninvaded zone still holds the original pore fluids, so its resistivity Rt is the one saturation equations require.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 7, 'A density reading taken across a washout is typically biased', '["high, because mudcake is denser than rock","high, because the pad presses harder against the wall","low, because the pad partly reads mud at about 1 g/cc","not at all, because density tools are immune to hole conditions"]'::jsonb, 2, 'The density tool is a pad tool; bridging a cave lets light mud into the measured volume, faking extra porosity.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 8, 'Which log is compared against bit size to detect washouts?', '["Gamma ray","Caliper","Deep resistivity","Neutron porosity"]'::jsonb, 1, 'The caliper measures actual hole diameter, so hole enlargement beyond bit size flags washouts.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 9, 'Depth of investigation describes', '["the thinnest bed a tool can resolve","the total depth a logging run reaches","the sampling increment of the digital log","how far radially into the formation a measurement reaches"]'::jsonb, 3, 'Depth of investigation is radial reach; vertical resolution is the thinnest resolvable bed.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 10, 'In the vertical typewell, how do measured depth and true vertical depth relate?', '["They coincide because the well is vertical","MD is always smaller than TVD","TVD exceeds MD by the drill floor elevation","They diverge below 2050 m"]'::jsonb, 0, 'MD and TVD only diverge in deviated wells; the teaching well is vertical.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 11, 'The typewell is sampled every 0.5 m from 2000 to 2100 m. How many samples does each curve hold, endpoints included?', '["200","100","201","1000"]'::jsonb, 2, '100 m at 0.5 m spacing gives 200 intervals, hence 201 samples including both ends.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 12, 'If 36 samples at 0.5 m spacing pass all pay criteria in a zone, the net pay thickness is', '["36 m","18 m","72 m","7.2 m"]'::jsonb, 1, 'Thickness is sample count times increment: 36 times 0.5 m equals 18 m.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 13, 'In this course, sonic slowness DT is carried in', '["microseconds per foot","metres per second","ohm.m","microseconds per metre"]'::jsonb, 3, 'The dataset is metric; the sand matrix slowness is 182 us/m, and mixing unit systems corrupts formulas silently.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 14, 'Which statement about the typewell zones is correct?', '["SAND_A spans 2010 to 2030 m and SAND_B spans 2050 to 2080 m","SAND_A spans 2050 to 2080 m and SAND_B spans 2010 to 2030 m","Both sands lie above 2010 m","The water leg lies inside SAND_A"]'::jsonb, 0, 'SAND_A is the shallower main target; SAND_B is deeper and carries the water leg at 2075 to 2078 m near its base.'),
  ('petrophysics', 'beginner', 'module', 'm01-logs-and-the-typewell', 15, 'The given clay line for the typewell is 120 API. Which observation directly supports it?', '["The sand at 2020 m reads GR 20 API","The water leg sits at 2075 to 2078 m","The shale at 2000 m reads about GR 120 API","The matrix density is 2.65 g/cc"]'::jsonb, 2, 'Given parameters should be confronted with the curves; the bounding shale reading matches the clay line.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 1, 'What does the gamma ray tool actually measure?', '["Gamma radiation emitted by a source in the tool and scattered back","Natural gamma radiation from potassium, thorium and uranium in the formation","The formation''s response to neutron bombardment","The electrical conductivity of the formation"]'::jsonb, 1, 'The GR tool is passive. It counts natural radioactivity from K, Th and U; it emits nothing into the rock.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 2, 'Why does shale normally read high on the gamma ray log?', '["Shale is denser than sandstone","Shale pore water is saline and conductive","Clay minerals hold potassium and adsorb thorium and uranium","Shale contains more quartz than sandstone"]'::jsonb, 2, 'Clays carry K-40 in their structure and their large surface area adsorbs Th and U, so clay-rich rocks are radioactive.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 3, 'A clean limestone interval reads 15 API. What is the correct beginner-level conclusion?', '["The interval is not shale, but low GR alone does not prove it is sandstone","The interval is a clean sandstone","The tool has failed, since nothing reads below 20 API","The interval is organic-rich shale"]'::jsonb, 0, 'Clean carbonates also read very low GR. Low GR means not shale; lithology needs the porosity logs too.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 4, 'An arkosic sand rich in potassium feldspar reads 85 API. Treating this reading as clay volume would', '["correctly identify a shaly sand","have no effect on the interpretation","underestimate the clay content of the sand","overestimate the clay content and could condemn a good reservoir"]'::jsonb, 3, 'Feldspar potassium raises GR without adding clay, so a hot sand looks shaly on GR alone.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 5, 'Which curve from a spectral gamma ray tool is usually the better clay indicator when uranium effects are suspected?', '["The total GR curve","The uranium curve","The thorium curve","The potassium-uranium ratio"]'::jsonb, 2, 'Uranium is mobile and concentrates independently of clay, so the thorium response tracks clay more reliably.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 6, 'With gr_clean = 20 API and gr_clay = 120 API, what is IGR for a reading of 70 API?', '["0.70","0.50","0.58","0.35"]'::jsonb, 1, 'IGR = (70 - 20) / (120 - 20) = 50 / 100 = 0.50.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 7, 'With the typewell anchors (clean 20, clay 120), a noisy sample reads 12 API. What IGR does the workflow assign?', '["0","-0.08","0.08","0.12"]'::jsonb, 0, 'The raw value (12 - 20)/100 is negative, and IGR is clamped to the physical range [0, 1], so it becomes 0.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 8, 'With gr_clean = 20 and gr_clay = 120, which reading gives IGR = 0.25?', '["25 API","30 API","45 API","50 API"]'::jsonb, 2, 'IGR = (45 - 20)/100 = 0.25. With these anchors, IGR is the API reading above 20, divided by 100.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 9, 'Why is it bad practice to set the clean and clay lines from the single minimum and maximum GR samples in the well?', '["Extreme single samples are often noise, letting one bad sample control the whole calibration","The minimum and maximum are not recorded by logging tools","It makes IGR impossible to clamp","API units are not comparable within a single well"]'::jsonb, 0, 'Anchors should represent the clean and shale populations, typically read from a histogram, so noise does not set the calibration.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 10, 'If the clean line is set too high (for example 40 API when the true clean sand reads 20 API), the computed Vsh in clean sands will', '["be too low","be unaffected, since the transform corrects anchor errors","be exactly zero everywhere","be too high in some intervals and show phantom clay in others"]'::jsonb, 3, 'No transform can rescue wrong anchors. A high clean line pushes genuinely clean rock above IGR 0, creating clay that is not there.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 11, 'Why does the linear transform Vsh = IGR generally overstate clay volume in young sands?', '["Radioactivity concentrates in the clay fraction, so a little clay produces a lot of gamma signal","Young sands contain no radioactive elements","IGR cannot exceed 0.5 in young rocks","The gamma ray tool reads too low in young rocks"]'::jsonb, 0, 'Because the radioactive elements sit preferentially in clay and associated fines, gamma response rises faster than clay volume.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 12, 'Using Larionov tertiary, Vsh = 0.083 (2^(3.7 IGR) - 1), what is Vsh for IGR = 0.50?', '["0.50","0.30","0.22","0.08"]'::jsonb, 2, '2^1.85 = 3.605; 3.605 - 1 = 2.605; 0.083 x 2.605 = 0.216, about 0.22.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 13, 'Which transform is used for the typewell interpretation in this course, and why?', '["Linear, because the typewell sands are clean","Larionov older rocks, because the section is consolidated","Clavier, because it is the industry default","Larionov tertiary, because the typewell is a young clastic section"]'::jsonb, 3, 'Larionov tertiary is the age-appropriate default for young clastic sections and matches the app''s default method.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 14, 'On the typewell, the shale at 2000 m reads 120 API. What Vsh does Larionov tertiary assign to it?', '["Exactly 1.000","0.996","0.83","0.90"]'::jsonb, 1, 'IGR = 1, so Vsh = 0.083 x (2^3.7 - 1) = 0.083 x 12.00 = 0.996, which is 1 within the precision of the constant.'),
  ('petrophysics', 'beginner', 'module', 'm02-shale-volume', 15, 'Averaged over its pay, the SAND_A zone of the typewell has Vsh of about', '["0.003","0.05","0.25","0.50"]'::jsonb, 0, 'The typewell sands are deliberately very clean; SAND_A averages roughly 0.003, so shale volume does not limit its net pay.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 1, 'A rock has total porosity 0.22, of which 0.04 is isolated or clay-bound. What is its effective porosity?', '["0.22","0.26","0.18","0.04"]'::jsonb, 2, 'Effective porosity is the interconnected, producible share: 0.22 minus 0.04 leaves 0.18.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 2, 'Which porosity value in a clean, moderately buried sandstone should immediately raise suspicion?', '["0.45","0.21","0.15","0.08"]'::jsonb, 0, '0.45 approaches loose uncompacted sediment; in buried sandstone it usually signals a bad reading or wrong parameters.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 3, 'The density tool measures porosity by sensing which physical property?', '["Hydrogen content of the pore fluid","Electron density via Compton scattering of gamma rays","Travel time of a sound pulse","Natural radioactivity of the rock"]'::jsonb, 1, 'Gamma rays scatter off electrons, and the returning count rate calibrates to bulk mass density.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 4, 'With rho_ma = 2.65 and rho_fl = 1.0, what porosity does RHOB = 2.3035 g/cc give?', '["0.35","0.13","0.17","0.21"]'::jsonb, 3, '(2.65 - 2.3035)/(2.65 - 1.0) = 0.3465/1.65 = 0.21.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 5, 'With rho_ma = 2.65 and rho_fl = 1.0, what porosity does RHOB = 2.485 g/cc give?', '["0.10","0.165","0.05","0.20"]'::jsonb, 0, '(2.65 - 2.485)/1.65 = 0.165/1.65 = 0.10.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 6, 'A shale reads RHOB = 2.55 g/cc. Using sandstone parameters (2.65, 1.0) the equation returns about 0.06. How should you treat that value?', '["Book it as producible reservoir porosity","Average it with the sand porosity","Treat it as apparent porosity that is mostly bound water, effectively non-productive","Double it to correct for clay"]'::jsonb, 2, 'Sandstone parameters applied to shale give an apparent value dominated by clay-bound water, which cannot flow.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 7, 'The neutron tool primarily responds to which constituent of the formation?', '["Silicon in the matrix","Hydrogen in pore fluids and clays","Iron in heavy minerals","Potassium in feldspars"]'::jsonb, 1, 'Neutrons slow fastest against hydrogen nuclei, so the tool measures hydrogen index as a porosity proxy.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 8, 'In a gas-bearing clean sand, what happens on a neutron-density overlay?', '["Both curves read high porosity","Neutron reads high while density reads low","The curves track each other exactly","Neutron reads low, density porosity reads high, and the curves cross over"]'::jsonb, 3, 'Gas has little hydrogen (neutron low) and low mass density (density porosity high), producing the classic gas crossover.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 9, 'Using Wyllie with dt_ma = 182 us/m and dt_fl = 656 us/m, what porosity does a transit time of 229.4 us/m give?', '["0.20","0.10","0.15","0.35"]'::jsonb, 1, '(229.4 - 182)/(656 - 182) = 47.4/474 = 0.10.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 10, 'Why does a shale read high on the neutron log even when its effective porosity is near zero?', '["Clay minerals hold structural hydrogen and bound water","Shale is denser than sandstone","Shale conducts electricity well","The tool pad loses contact in shale"]'::jsonb, 0, 'The neutron tool counts all hydrogen, including hydrogen in clay lattices and bound water that stores no producible fluid.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 11, 'Recomputing a sand point (RHOB = 2.3035) with a limestone matrix of 2.71 instead of quartz 2.65 changes porosity from 0.210 to about:', '["0.182","0.210","0.238","0.290"]'::jsonb, 2, '(2.71 - 2.3035)/(2.71 - 1.0) = 0.4065/1.71 = 0.2377, about 2.8 porosity units too high.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 12, 'Assuming a matrix density heavier than the true one has what effect on computed density porosity?', '["No effect","Raises it","Lowers it","Makes it read exactly zero"]'::jsonb, 1, 'A larger rho_ma inflates the numerator more than the denominator, so porosity reads too high.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 13, 'Which pair of parameter values does the typewell interpretation use for density porosity?', '["rho_ma = 2.71, rho_fl = 1.1","rho_ma = 2.87, rho_fl = 1.0","rho_ma = 2.65, rho_fl = 0.7","rho_ma = 2.65, rho_fl = 1.0"]'::jsonb, 3, 'Quartz sand grains at 2.65 g/cc and fresh mud filtrate at 1.0 g/cc are the dataset givens.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 14, 'The pay-quality porosity averages of SAND_A and SAND_B are approximately:', '["0.21 and 0.14","0.14 and 0.21","0.25 and 0.08","0.21 and 0.06"]'::jsonb, 0, 'SAND_A pay averages about 0.208 while the thinner SAND_B pay averages about 0.142.'),
  ('petrophysics', 'beginner', 'module', 'm03-porosity', 15, 'A density log reads below zero porosity in a known tight streak. The most likely cause is:', '["Negative porosity is common in tight rock","Gas in the invaded zone","The assumed matrix density is lighter than the true grain density","The mud filtrate is fresher than assumed"]'::jsonb, 2, 'When true grain density exceeds the assumed rho_ma, low-porosity readings push the computed value negative, revealing a matrix mismatch.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 1, 'Which component of a clean water bearing sandstone carries essentially all of the electric current measured by a resistivity tool?', '["The quartz grain framework","The dissolved ions in the formation brine","The hydrocarbon in the pores","The cement between grains"]'::jsonb, 1, 'Mineral grains and hydrocarbons are insulators for practical purposes; conduction happens through the ions dissolved in the pore brine.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 2, 'A deep resistivity measurement is designed to read past the invaded zone. What quantity is it targeting?', '["Rxo, the flushed zone resistivity","Rmf, the mud filtrate resistivity","Rt, the true formation resistivity","Rw, the formation water resistivity"]'::jsonb, 2, 'The deep reading aims at the undisturbed formation beyond invasion, which is the true resistivity Rt used in saturation work.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 3, 'Why is resistivity displayed on a logarithmic scale?', '["Because the tool outputs logarithms directly","Because resistivity spans several orders of magnitude and ratios carry the meaning","Because saturation is a logarithmic quantity","Because invasion effects are exponential with depth"]'::jsonb, 1, 'Ordinary rocks read from fractions of an ohm.m to thousands, and interpretation works in ratios such as Rt over R0, so a log scale is natural.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 4, 'An Rw value is quoted without a temperature. Why is that a problem?', '["Rw falls as temperature rises, so the value is meaningless without its temperature","Rw rises as temperature rises, so the value is only a minimum","Temperature only matters for oil based muds","It is not a problem because Rw is independent of temperature"]'::jsonb, 0, 'Warmer brine conducts better, so the same water can differ by a factor of two or more between surface and reservoir temperature.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 5, 'Which of the following is NOT a standard way to obtain Rw?', '["Measuring a produced water sample","Inverting the SP deflection","Back calculating apparent Rw in a known water leg","Reading it from the gamma ray curve"]'::jsonb, 3, 'The gamma ray responds to radioactivity and says nothing about brine salinity; the other three are the standard sources alongside the Pickett plot.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 6, 'With a = 1 and m = 2, what is the formation factor F of a sand with porosity 0.21?', '["About 4.8","About 10.5","About 22.7","About 45.4"]'::jsonb, 2, 'F = a / phi^m = 1 / 0.21^2 = 1 / 0.0441 which is about 22.7.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 7, 'Using the typewell givens (Rw 0.05, a 1, m 2, n 2), what is the wet baseline R0 for a sand with porosity 0.21?', '["0.05 ohm.m","1.134 ohm.m","2.268 ohm.m","9.26 ohm.m"]'::jsonb, 1, 'R0 = F Rw = (1 / 0.0441) x 0.05 = 1.134 ohm.m; the measured 9.26 ohm.m is about eight times this baseline.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 8, 'At 2020 m the typewell reads phi 0.2100 and Rt 9.2554 ohm.m. With Rw 0.05, a 1, m 2, n 2, the computed Sw is:', '["0.12","0.25","0.35","0.65"]'::jsonb, 2, 'phi^2 x Rt = 0.40824, the ratio 0.05 / 0.40824 = 0.12248, and its square root is 0.3500.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 9, 'A sample has phi 0.15 and Rt 5 ohm.m. With Rw 0.05, a 1, m 2, n 2, the computed Sw is closest to:', '["0.44","0.53","0.60","0.67"]'::jsonb, 3, 'phi^2 = 0.0225, phi^2 x Rt = 0.1125, ratio = 0.4444, square root = 0.667.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 10, 'With n = 2, using an Rw that is two times too large multiplies every computed Sw by about:', '["1.19","1.41","2.00","4.00"]'::jsonb, 1, 'Sw scales as the square root of Rw when n = 2, and the square root of 2 is about 1.41.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 11, 'In the physical reading of the Archie exponents, the cementation exponent m describes:', '["How salty the formation brine is","How tortuous the electrical paths through the pore network are","How much clay the rock contains","How the brine film breaks up as hydrocarbons enter"]'::jsonb, 1, 'm captures pore geometry: more cemented, more tortuous rocks force longer current paths and carry a higher m.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 12, 'Plain Archie is applied in a sand with Vsh of 0.35. The most likely error in the computed saturation is:', '["Sw is overstated because clay conductivity is read as extra water","Sw is understated because clay blocks the current","There is no error because Archie handles clay","Sw is exactly 1.0 regardless of fluids"]'::jsonb, 0, 'Clay surfaces conduct, which lowers resistivity, and plain Archie interprets the extra conductivity as extra water; shaly sand models such as Simandoux correct for this.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 13, 'In an oil wet rock, the effective saturation exponent n tends to be higher than 2 because:', '["The brine becomes saltier","Oil conducts part of the current","The remaining water sits in poorly connected blobs instead of a connected film","Porosity is destroyed by oil wetting"]'::jsonb, 2, 'Without a connected water film on the grains, resistivity climbs much faster as water saturation falls, which shows up as a larger n.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 14, 'The standard first check that the Rw and parameter set are consistent on the typewell is:', '["Confirming SAND_A computes Sw near 0.35","Confirming the shale computes Sw near zero","Confirming the known water leg at 2075 to 2078 m computes Sw near 1.0","Confirming the gamma ray reads 20 API in the sands"]'::jsonb, 2, 'A known fully water bearing interval must return Sw near 1; a value away from 1 there isolates an input error before any pay is interpreted.'),
  ('petrophysics', 'beginner', 'module', 'm04-resistivity-and-saturation', 15, 'Averaged over its 18.0 m of net pay, SAND_A on the typewell carries a water saturation of about:', '["0.21","0.36","0.54","0.88"]'::jsonb, 1, 'SAND_A averages Sw 0.361 over its net pay, so roughly two thirds of the pore volume holds hydrocarbons.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 1, 'A sample is flagged as net pay when:', '["any one of the porosity, shale volume or saturation tests passes","at least two of the three cutoff tests pass","all three cutoff tests pass at the same time","its porosity alone exceeds the porosity cutoff"]'::jsonb, 2, 'The pay test is a logical AND of the porosity, shale volume and saturation conditions. One failed test makes the sample non-pay.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 2, 'Which set of test directions is correct for the pay flag?', '["phi >= cutoff, Vsh <= cutoff, Sw <= cutoff","phi <= cutoff, Vsh <= cutoff, Sw <= cutoff","phi >= cutoff, Vsh >= cutoff, Sw <= cutoff","phi >= cutoff, Vsh <= cutoff, Sw >= cutoff"]'::jsonb, 0, 'More porosity is good, so it must be at or above its cutoff; shale volume and water saturation are bad, so they must be at or below theirs.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 3, 'Net reservoir differs from net pay because net reservoir:', '["includes only hydrocarbon-bearing rock","applies the saturation cutoff but not the shale cutoff","is always thinner than net pay","counts rock that could store and flow fluid regardless of what fluid is in it"]'::jsonb, 3, 'Net reservoir passes the porosity and shale filters only. The saturation filter then removes wet rock to leave net pay.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 4, 'A sample has phi = 0.10, Vsh = 0.55 and Sw = 0.40. Against cutoffs phi >= 0.08, Vsh <= 0.5, Sw <= 0.6 it is:', '["pay, because two of three tests pass","not pay, because the shale volume test fails","not pay, because the porosity test fails","pay, because saturation is well below its cutoff"]'::jsonb, 1, 'Vsh = 0.55 exceeds the 0.5 cutoff, and a single failed test makes the sample non-pay.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 5, 'On a log sampled every 0.5 m, 24 samples in a zone pass all three cutoff tests. The net pay thickness is:', '["24 m","48 m","6 m","12 m"]'::jsonb, 3, 'Each flagged sample represents 0.5 m, so 24 x 0.5 = 12 m.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 6, 'The most defensible source for a porosity cutoff value is:', '["the porosity of the best sample in the well","a core porosity-permeability crossplot read at a minimum useful permeability","the average porosity of the gross interval","the value used on the previous well regardless of rock type"]'::jsonb, 1, 'Cutoffs stand in for a permeability floor, and core calibration ties the porosity threshold to the permeability the reservoir needs to flow.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 7, 'Tightening the saturation cutoff from 0.6 to 0.5 while nothing else changes:', '["can only keep net pay the same or reduce it","can only increase net pay","can move net pay in either direction","changes gross thickness but never net"]'::jsonb, 0, 'Every sample passing the tighter test also passes the looser one, so the filter can only remove samples.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 8, 'Six pay samples (0.5 m each) have saturations 0.35, 0.35, 0.42, 0.48, 0.55, 0.58. After tightening Sw_cut from 0.6 to 0.5 the net pay becomes:', '["3.0 m","2.5 m","2.0 m","1.5 m"]'::jsonb, 2, 'The samples at 0.55 and 0.58 now fail, leaving four samples: 4 x 0.5 = 2.0 m.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 9, 'Why must reported net pay always be accompanied by the cutoffs used?', '["because regulators require three significant figures","because net pay has units of metres","because cutoffs change with logging tool vendor","because the same curves give different net pay under different cutoffs, so the number alone is not reproducible"]'::jsonb, 3, 'Net pay is defined by the filters applied. Without the cutoff values, another interpreter cannot reproduce or fairly compare the number.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 10, 'Pay-average porosity is computed over:', '["all samples between the zone top and base","only the samples flagged as pay","only the samples that failed the cutoffs","the whole logged interval of the well"]'::jsonb, 1, 'The averages must describe the same samples the net thickness counts, otherwise the summary row is internally inconsistent.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 11, 'A zone has gross 10.5 m and 15 pay samples at 0.5 m sampling. Its NTG is:', '["0.50","0.65","0.71","0.75"]'::jsonb, 2, 'Net is 15 x 0.5 = 7.5 m, and 7.5 / 10.5 = 0.714.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 12, 'Averaging porosity over the gross interval instead of the pay samples typically:', '["understates the porosity of the bookable rock","overstates the porosity of the bookable rock","has no effect if the zone contains any shale","is required for volumetric calculations"]'::jsonb, 0, 'Gross averaging dilutes the pay with shales, tight streaks and wet rock, pulling the average below what the booked rock actually has.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 13, 'SAND_A books gross 20.5 m for a zone defined from 2010 to 2030 m because:', '["the zone boundaries were picked half a metre too deep","net pay was added to the gross thickness","the software rounds thickness up to the next half metre","samples at both bounding depths are counted, giving 41 samples times 0.5 m"]'::jsonb, 3, 'The zone includes every sample from 2010.0 to 2030.0 inclusive, one extra sample increment over the nominal 20 m difference.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 14, 'On the typewell, SAND_B has the larger gross interval (30.5 m against 20.5 m) yet books far less pay than SAND_A (5.5 m against 18.0 m) mainly because:', '["its shale volume exceeds the cutoff across most of the zone","much of it is too tight and its lower part is wet, including the water leg","its zone boundaries were drawn incorrectly","the density log was not run across SAND_B"]'::jsonb, 1, 'Long runs of SAND_B fall below the porosity floor and saturation climbs with depth, with the 2075 to 2078 m water leg failing the Sw test outright.'),
  ('petrophysics', 'beginner', 'module', 'm05-cutoffs-and-net-pay', 15, 'With net pay 18.0 m, pay-average porosity 0.208 and pay-average Sw 0.361, the hydrocarbon-filled porosity thickness of SAND_A is closest to:', '["1.35 m","3.74 m","2.39 m","0.68 m"]'::jsonb, 2, '18.0 x 0.208 x (1 - 0.361) = 18.0 x 0.208 x 0.639 = 2.39 m.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 1, 'In the beginner workflow, why must porosity be computed before water saturation?', '["Because the density tool is run before the resistivity tool","Because porosity appears inside the Archie equation, so saturation consumes it","Because cutoffs are applied to porosity first","Because shale volume depends on porosity"]'::jsonb, 1, 'The workflow is a chain: Archie takes phi as an input, so Sw cannot be computed until porosity exists.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 2, 'Which is the correct order of the beginner interpretation pipeline?', '["Vsh, porosity, saturation, cutoffs and summaries","Porosity, Vsh, cutoffs, saturation","Saturation, porosity, Vsh, cutoffs","Cutoffs, Vsh, porosity, saturation"]'::jsonb, 0, 'Shale volume and porosity come from their own curves, saturation consumes porosity, and cutoffs test all three at the end.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 3, 'At 2020 m the typewell reads GR 20, RHOB 2.3035 and RT 9.2554. What does the full workflow conclude for this sample?', '["It fails the saturation cutoff","It fails the porosity cutoff","It passes all three cutoffs and is flagged as pay","It is excluded as bad hole"]'::jsonb, 2, 'The sample computes Vsh 0, phiD 0.2100 and Sw 0.3500, which pass all three cutoff tests.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 4, 'A sample computes Sw incorrectly. Following the chain logic of the workflow, where should you look first for the root cause?', '["The zone summary code","The cutoff values","The reporting template","The earliest upstream inputs, such as the porosity parameters feeding Archie"]'::jsonb, 3, 'Errors flow downstream, so the fault is usually at the earliest stage whose input was mis-set.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 5, 'Which reading would fail a basic curve-range check on the typewell?', '["A bulk density of 1.02 g/cc in open sand","A gamma ray of 120 API in shale","A deep resistivity of 9 ohm.m in sand","A bulk density of 2.55 g/cc in shale"]'::jsonb, 0, 'A density near 1 g/cc means the pad read mud; the other readings are plausible formation values.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 6, 'What is the classic log signature of bad hole affecting the density measurement?', '["Gamma ray dropping to zero","Caliper reading well over bit size with a density spike toward low values","Resistivity and density increasing together","Neutron porosity reading exactly zero"]'::jsonb, 1, 'The pad loses contact in washouts, so caliper over gauge with a low-density spike marks suspect porosity.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 7, 'Why is the water leg at 2075 to 2078 m so valuable for quality control?', '["It marks the deepest sample of the log","It gives the highest porosity in the well","A correct parameter set must compute Sw near 1 there, which validates Rw against data","It defines the gamma ray clay line"]'::jsonb, 2, 'A fully water saturated sand must return Sw near 1, so the water leg pins Rw independently of assumption.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 8, 'The shale at 2000 m computes Vsh near 0.996 and phiD near 0.06. What does this tell the interpreter?', '["The clay line is set far too high","The zone should be flagged as pay","The density log is reading bad hole","The Vsh calibration is behaving correctly for a known shale"]'::jsonb, 3, 'A known shale computing Vsh near 1 with low apparent porosity is exactly the expected calibration response.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 9, 'If the water leg computes an average Sw of 0.7 with all other inputs correct, what is the most likely error?', '["The Rw used is too low","The Rw used is too high","The porosity cutoff is too tight","The clay line is too low"]'::jsonb, 0, 'Sw scales with the square root of Rw, so an Rw set too low pulls computed saturations below their true values.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 10, 'With n = 2, how does a factor of 2 error in Rw propagate into Sw?', '["Sw changes by a factor of 4","Sw changes by a factor of about 1.41","Sw changes by a factor of 2","Sw is unaffected because Rw cancels"]'::jsonb, 1, 'Sw is proportional to the square root of Rw, and the square root of 2 is about 1.41.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 11, 'Using a limestone matrix density of 2.71 g/cc instead of the correct 2.65 g/cc on the typewell sand mainly causes:', '["Random noise in the porosity curve","No change, because the fluid density compensates","A change only inside the shale intervals","A systematic offset of roughly +0.028 in density porosity across the well"]'::jsonb, 3, 'Matrix density errors shift nearly every sample by a similar amount, so the error is systematic rather than random.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 12, 'Why is SAND_B''s net pay more sensitive to cutoff choices than SAND_A''s?', '["SAND_B is thinner in gross terms","SAND_B has a much higher shale volume","Much of SAND_B sits close to the porosity and saturation cutoff values, so small cutoff moves flip many samples","SAND_A was logged with a better tool"]'::jsonb, 2, 'Cutoff sensitivity depends on how much rock crowds the cutoff lines, and SAND_B fails or passes narrowly through much of its section.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 13, 'What is the core discipline of a proper sensitivity analysis?', '["Change one input at a time, rerun, record the change, then restore it","Change all uncertain inputs together to see the worst case","Only vary the cutoffs, since parameters are given","Rerun the workflow twice with the same inputs"]'::jsonb, 0, 'One-at-a-time changes keep every observed delta attributable to a single cause.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 14, 'Which item belongs in a petrophysical summary specifically so that a reviewer can reproduce the results?', '["A list of nearby wells","The complete parameter table used by the workflow","The interpreter''s estimate of drilling cost","A seismic section through the well"]'::jsonb, 1, 'The parameter table is the audit trail; with it and the cutoffs a reviewer can recompute every reported number.'),
  ('petrophysics', 'beginner', 'module', 'm06-the-interpretation-loop', 15, 'In the reported zone table for the typewell, SAND_A shows which set of values?', '["Gross 30.5 m, net 5.5 m, NTG 0.180","Gross 20.5 m, net 20.5 m, NTG 1.000","Gross 18.0 m, net 20.5 m, NTG 0.878","Gross 20.5 m, net 18.0 m, NTG 0.878"]'::jsonb, 3, 'SAND_A spans 20.5 m gross of which 18.0 m passes all cutoffs, giving a net-to-gross of 0.878.'),
  ('petrophysics', 'beginner', 'final', null, 1, 'What does the gamma ray (GR) log actually measure?', '["The electrical conductivity of the formation","The hydrogen content of the pore fluid","Natural radioactivity from potassium, thorium and uranium in the rock","The bulk density of the formation"]'::jsonb, 2, 'The GR tool counts natural gamma radiation, which comes mostly from potassium, thorium and uranium concentrated in clay minerals, which is why GR is the workhorse shale indicator.'),
  ('petrophysics', 'beginner', 'final', null, 2, 'Which log responds primarily to the electron density of the formation and is the main input for density porosity?', '["The bulk density (RHOB) log","The gamma ray log","The deep resistivity log","The caliper log"]'::jsonb, 0, 'The density tool''s gamma-gamma scattering measurement responds to electron density, which is converted to bulk density RHOB, the input to density porosity.'),
  ('petrophysics', 'beginner', 'final', null, 3, 'Mud filtrate invades the formation near the wellbore during drilling. A shallow-reading resistivity device therefore measures which quantity?', '["The true formation resistivity Rt","The flushed zone resistivity Rxo","The formation water resistivity Rw","The mud cake resistivity"]'::jsonb, 1, 'Shallow devices read the invaded (flushed) zone Rxo where filtrate has displaced formation fluid; deep devices are designed to see past invasion toward Rt.'),
  ('petrophysics', 'beginner', 'final', null, 4, 'Why should you check the caliper log before trusting density porosity in an interval?', '["The caliper measures formation radioactivity, which corrects RHOB","The caliper gives the mud weight needed for the fluid density","The caliper confirms the depth reference for the whole log set","Washouts break the density pad''s contact with the borehole wall and corrupt RHOB"]'::jsonb, 3, 'The density tool is a pad device; in washed-out hole the pad loses contact and reads mud instead of rock, so enlarged caliper flags unreliable RHOB.'),
  ('petrophysics', 'beginner', 'final', null, 5, 'A well is logged from 2000 m to 2100 m with a sample every 0.5 m, including both end depths. How many samples is that?', '["200","100","201","50"]'::jsonb, 2, '100 m at 0.5 m spacing gives 200 intervals, and counting both end points yields 201 samples.'),
  ('petrophysics', 'beginner', 'final', null, 6, 'Which set of units matches GR, RHOB and Rt as recorded in a metric log set like the typewell?', '["API units, g/cm3, ohm.m","ohm.m, API units, g/cm3","percent, kg/m3, millivolts","counts per second, ohm.m, g/cm3"]'::jsonb, 0, 'Gamma ray is reported in API units, bulk density in g/cm3 and resistivity in ohm.m.'),
  ('petrophysics', 'beginner', 'final', null, 7, 'With a clean line of 20 API and a clay line of 120 API, what is IGR at a GR reading of 45 API?', '["0.45","0.25","0.20","0.30"]'::jsonb, 1, 'IGR = (45 - 20) / (120 - 20) = 25 / 100 = 0.25.'),
  ('petrophysics', 'beginner', 'final', null, 8, 'With clean 20 API and clay 120 API, a caved shale reads 145 API. What IGR should you carry forward?', '["1.25","1.45","1.00","0.80"]'::jsonb, 2, 'The raw ratio gives 1.25, but IGR is clamped to the 0 to 1 range because a rock cannot be more than 100 percent shale.'),
  ('petrophysics', 'beginner', 'final', null, 9, 'Using the Larionov tertiary transform Vsh = 0.083 (2^(3.7 IGR) - 1), what is Vsh at IGR = 0.5?', '["0.500","0.216","0.083","0.350"]'::jsonb, 1, '2^1.85 is about 3.606, minus 1 gives 2.606, times 0.083 gives about 0.216.'),
  ('petrophysics', 'beginner', 'final', null, 10, 'For the same IGR between 0 and 1, how does Larionov tertiary Vsh compare with the linear transform Vsh = IGR?', '["It is always higher","It is identical","It is higher below IGR 0.5 and lower above","It is lower"]'::jsonb, 3, 'The tertiary curve bows below the one-to-one line everywhere between the end points, so it always gives less shale than the linear transform for the same IGR.'),
  ('petrophysics', 'beginner', 'final', null, 11, 'Why is the Larionov tertiary transform often preferred over the linear transform in young, unconsolidated basins?', '["It was calibrated for Tertiary rocks, where the linear transform systematically overestimates Vsh","It removes the need to pick a clay line","It corrects the GR log for borehole washout","It works even when the sand is radioactive"]'::jsonb, 0, 'Larionov''s tertiary calibration reflects how GR maps to actual clay content in young rocks, where taking IGR directly as Vsh reads too much shale.'),
  ('petrophysics', 'beginner', 'final', null, 12, 'With clean 20 API and clay 120 API, a shale bed reads exactly 120 API. Under Larionov tertiary, its Vsh is closest to:', '["0.50","0.83","0.90","1.00"]'::jsonb, 3, 'At the clay line IGR = 1 and the tertiary transform gives 0.083 (2^3.7 - 1), which is about 0.996, effectively 1.'),
  ('petrophysics', 'beginner', 'final', null, 13, 'A clean sand contains potassium feldspar and mica and therefore reads high GR (a hot sand). What does a GR-based Vsh do there?', '["It underestimates shale volume","It overestimates shale volume","It is unaffected because feldspar is not radioactive","It fails only if the mud is barite weighted"]'::jsonb, 1, 'The high GR comes from radioactive minerals rather than clay, so a GR-only Vsh flags clean rock as shaly and overestimates Vsh.'),
  ('petrophysics', 'beginner', 'final', null, 14, 'With matrix density 2.65 g/cm3 and fluid density 1.0 g/cm3, what porosity does RHOB = 2.485 g/cm3 give?', '["0.10","0.165","0.20","0.08"]'::jsonb, 0, 'phiD = (2.65 - 2.485) / (2.65 - 1.0) = 0.165 / 1.65 = 0.10.'),
  ('petrophysics', 'beginner', 'final', null, 15, 'With matrix 2.65 g/cm3 and fluid 1.0 g/cm3, what porosity does RHOB = 2.32 g/cm3 give?', '["0.14","0.33","0.20","0.25"]'::jsonb, 2, 'phiD = (2.65 - 2.32) / 1.65 = 0.33 / 1.65 = 0.20.'),
  ('petrophysics', 'beginner', 'final', null, 16, 'A log sample reads RHOB = 2.65 g/cm3 with matrix density 2.65 g/cm3 and fluid density 1.0 g/cm3. The density porosity is:', '["0.08","0.00","1.00","0.65"]'::jsonb, 1, 'When bulk density equals matrix density there is no fluid-filled pore space in the measurement, so phiD = 0.'),
  ('petrophysics', 'beginner', 'final', null, 17, 'You process a quartz sandstone (true matrix 2.65 g/cm3) using a limestone matrix of 2.71 g/cm3. At RHOB = 2.485 g/cm3 the computed porosity changes from 0.10 to about:', '["0.13, roughly 0.03 too high","0.07, roughly 0.03 too low","0.10, no change","0.20, roughly double"]'::jsonb, 0, 'phiD = (2.71 - 2.485) / (2.71 - 1.0) = 0.225 / 1.71, about 0.132, so the wrong heavier matrix inflates porosity by about 0.03.'),
  ('petrophysics', 'beginner', 'final', null, 18, 'On a compatible neutron-density overlay, gas in the pores classically shows up as:', '["Both porosities reading high together","Both porosities reading low together","Density porosity high and neutron porosity low, the curves crossing over","No effect, because gas is not conductive"]'::jsonb, 2, 'Gas lowers bulk density (raising phiD) and has little hydrogen (lowering neutron porosity), producing the crossover signature.'),
  ('petrophysics', 'beginner', 'final', null, 19, 'Besides the measured transit time DT, which two constants does the Wyllie time-average sonic porosity need?', '["Matrix density and fluid density","Clean line and clay line","Formation water resistivity and cementation exponent","Matrix transit time and fluid transit time"]'::jsonb, 3, 'Wyllie interpolates the measured DT between the matrix transit time and the pore fluid transit time to estimate porosity.'),
  ('petrophysics', 'beginner', 'final', null, 20, 'Effective porosity differs from total porosity because effective porosity excludes:', '["All porosity below the porosity cutoff","Clay-bound water and isolated, unconnected pores","Pores filled with hydrocarbons","The flushed zone porosity"]'::jsonb, 1, 'Effective porosity counts only the connected, producible pore volume, leaving out clay-bound water and isolated pores that total porosity includes.'),
  ('petrophysics', 'beginner', 'final', null, 21, 'With a = 1 and m = 2, what is the formation factor F at porosity 0.20?', '["5","25","50","10"]'::jsonb, 1, 'F = a / phi^m = 1 / 0.2^2 = 1 / 0.04 = 25.'),
  ('petrophysics', 'beginner', 'final', null, 22, 'A fully water-bearing rock has porosity 0.10, a = 1, m = 2 and Rw = 0.05 ohm.m. What resistivity R0 should it read?', '["0.5 ohm.m","2.0 ohm.m","5.0 ohm.m","10.0 ohm.m"]'::jsonb, 2, 'F = 1 / 0.01 = 100 and R0 = F Rw = 100 x 0.05 = 5 ohm.m.'),
  ('petrophysics', 'beginner', 'final', null, 23, 'Using Archie with a = 1, m = 2, n = 2 and Rw = 0.05 ohm.m, what is Sw at porosity 0.10 and Rt = 20 ohm.m?', '["0.25","0.50","0.35","0.71"]'::jsonb, 1, 'Sw = sqrt(a Rw / (phi^m Rt)) = sqrt(0.05 / (0.01 x 20)) = sqrt(0.25) = 0.50.'),
  ('petrophysics', 'beginner', 'final', null, 24, 'At 2020 m the typewell reads porosity 0.21 and Rt = 9.2554 ohm.m, with a = 1, m = 2, n = 2, Rw = 0.05 ohm.m. Sw is closest to:', '["0.35","0.21","0.50","0.65"]'::jsonb, 0, 'phi^2 = 0.0441, so Sw = sqrt(0.05 / (0.0441 x 9.2554)) = sqrt(0.1225) = 0.35.'),
  ('petrophysics', 'beginner', 'final', null, 25, 'With n = 2, if the Rw you assume is doubled while everything else stays fixed, the computed Sw:', '["doubles","is unchanged","falls by a factor of 1.41","rises by a factor of about 1.41"]'::jsonb, 3, 'Sw is proportional to the square root of Rw when n = 2, so doubling Rw multiplies Sw by sqrt(2), about 1.41.'),
  ('petrophysics', 'beginner', 'final', null, 26, 'The basic Archie equation is safe to apply only when:', '["The zone is at irreducible water saturation","The porosity is above 15 percent","The rock is clean (essentially clay free) and brine is the only conductor","The mud filtrate is fresher than the formation water"]'::jsonb, 2, 'Archie assumed the brine network is the only conductive path; conductive clay adds a second path and makes plain Archie overestimate Sw in shaly rock.'),
  ('petrophysics', 'beginner', 'final', null, 27, 'Using Archie with a = 1, m = 2, n = 2, Rw = 0.05 ohm.m, porosity 0.20 and Rt = 20 ohm.m, Sw is:', '["0.50","0.35","0.71","0.25"]'::jsonb, 3, 'Sw = sqrt(0.05 / (0.04 x 20)) = sqrt(0.0625) = 0.25.'),
  ('petrophysics', 'beginner', 'final', null, 28, 'With cutoffs phi >= 0.08, Vsh <= 0.5 and Sw <= 0.6, a sample counts as pay when:', '["It passes all three conditions at once","It passes any one of the three conditions","It passes the porosity cutoff, which outranks the others","It passes two of the three conditions"]'::jsonb, 0, 'Pay flagging is a logical AND: rock quality (phi, Vsh) and fluid content (Sw) must all qualify together.'),
  ('petrophysics', 'beginner', 'final', null, 29, 'A sample has phi = 0.12, Vsh = 0.30 and Sw = 0.70 against cutoffs phi >= 0.08, Vsh <= 0.5, Sw <= 0.6. Is it pay?', '["Yes, it passes all cutoffs","No, it fails the porosity cutoff","No, it fails the Vsh cutoff","No, it fails the Sw cutoff"]'::jsonb, 3, 'Porosity and Vsh both qualify, but Sw = 0.70 exceeds the 0.6 limit, so the sample is wet rock, not pay.'),
  ('petrophysics', 'beginner', 'final', null, 30, 'A zone''s samples are spaced 0.5 m apart and 24 of them are flagged as pay. The net pay thickness is:', '["24 m","12 m","6 m","48 m"]'::jsonb, 1, 'Each flagged sample represents 0.5 m of section, so net = 24 x 0.5 = 12 m.'),
  ('petrophysics', 'beginner', 'final', null, 31, 'SAND_A on the typewell has gross 20.5 m and net 18.0 m. Its net-to-gross is:', '["0.878","1.139","0.900","0.180"]'::jsonb, 0, 'NTG = net / gross = 18.0 / 20.5, which is about 0.878; dividing the other way round gives the impossible 1.139.'),
  ('petrophysics', 'beginner', 'final', null, 32, 'The typewell summaries give SAND_A: NTG 0.878, phi_avg 0.208, sw_avg 0.361 and SAND_B: NTG 0.180, phi_avg 0.142, sw_avg 0.542. Which zone is the better reservoir and why?', '["SAND_B, because its gross interval is thicker","They are equivalent because both contain pay","SAND_A, because it has higher net-to-gross and porosity with lower water saturation","SAND_B, because higher Sw means more recoverable fluid"]'::jsonb, 2, 'SAND_A wins on every quality measure: far more of its interval is pay, the pay is more porous, and it holds less water.'),
  ('petrophysics', 'beginner', 'final', null, 33, 'In a standard net pay summary, the reported average porosity phi_avg is computed over:', '["Every sample in the gross interval","Only the samples that fail the cutoffs","The whole logged well","Only the samples flagged as pay"]'::jsonb, 3, 'Zone averages characterise the pay itself, so they are taken over pay-flagged samples only; averaging over gross would dilute them with non-reservoir rock.'),
  ('petrophysics', 'beginner', 'final', null, 34, 'The typewell water leg at 2075 to 2078 m computes Sw close to 1.0 with Rw = 0.05 ohm.m. What does this tell the interpreter?', '["The chosen Rw is consistent, because a known water zone should compute fully water saturated","The zone contains residual hydrocarbons","The porosity model is wrong in the water leg","The cutoffs are too strict"]'::jsonb, 0, 'A known water-bearing interval is the standard check on Rw: computing Sw of about 1 there says the saturation model and Rw are self-consistent.'),
  ('petrophysics', 'beginner', 'final', null, 35, 'Which sequence states the beginner interpretation workflow in the correct order?', '["Cutoffs, then Sw, then porosity, then Vsh","Rt to Sw, then GR to Vsh, then net pay, then porosity","GR to Vsh, RHOB to porosity, Rt plus porosity to Sw, then cutoffs to net pay","RHOB to porosity, then cutoffs, then GR to Vsh, then Sw"]'::jsonb, 2, 'Lithology and porosity come first because Sw needs porosity as an input, and the cutoffs are applied last to flag pay from all three curves.'),
  ('petrophysics', 'beginner', 'final', null, 36, 'As a sanity check, you compute Vsh in the thick shale at the top of the typewell (GR at the 120 API clay line). A healthy result is approximately:', '["0.5","0.083","0.25","1.0"]'::jsonb, 3, 'A known shale should come out essentially all shale; Larionov tertiary at IGR = 1 gives about 0.996, so a value near 1 confirms the clean and clay lines.'),
  ('petrophysics', 'beginner', 'final', null, 37, 'Density porosity looks suspiciously high across one interval. The first log to inspect is:', '["The deep resistivity, to rule out hydrocarbons","The caliper, to check for washout where the density pad lost contact","The gamma ray, to re-pick the clay line","The SP, to estimate Rw"]'::jsonb, 1, 'Bad hole is the most common cause of falsely high density porosity, and the caliper tells you immediately whether the interval is washed out.'),
  ('petrophysics', 'beginner', 'final', null, 38, 'The Petrophysics Beginner capstone grades exactly six numbers. They are:', '["Net thickness, average porosity and average water saturation for SAND_A and SAND_B","Gross, net and NTG for SAND_A and SAND_B","IGR, Vsh and phiD at three key depths","Rw, a, m, n, and the two cutoff values"]'::jsonb, 0, 'The capstone asks for net_m, phi_avg and sw_avg per zone, the six numbers a zone summary reports for each sand.'),
  ('petrophysics', 'beginner', 'final', null, 39, 'Which set of quantities belongs in a one-line summary of an evaluated zone?', '["GR, RHOB and Rt at the zone top","The mud weight, bit size and logging date","Gross, net, NTG, and pay-weighted average porosity and water saturation","The full list of per-sample pay flags"]'::jsonb, 2, 'Those five quantities condense the zone into the numbers volumetrics and decisions actually use; single-depth readings or raw flags are working data, not the summary.'),
  ('petrophysics', 'beginner', 'final', null, 40, 'Your water leg computes Sw of about 0.7 instead of 1.0 and you are confident the porosity is right. The most likely cause is:', '["The n exponent is too high","The zone is actually hydrocarbon bearing","The porosity cutoff is set too low","The Rw you assumed is lower than the true formation water resistivity"]'::jsonb, 3, 'Sw scales with sqrt(Rw), so an Rw that is too low pulls the computed Sw below 1 even in known water; the fix is to raise Rw until the water leg reads about 1.');
